        if ('0' <= b && b <= '7') { // if b is a valid character in the range [0-7], decode it
            sb.append((char) (b - '0'));
            i++; // move the index forward
        } else if (b == 128 || b == 192) { // if b is an UTF-8 byte starting a multibyte character
            byte c2;
            int nextIndex = i + 1;
            if (nextIndex < bb.remaining()) {
                c2 = bb.get(nextIndex); // get the second byte
                if (c2 >= 48 && c2 <= 63) { // b is the continuation byte of the multibyte character
                    sb.append((char) ((b - 128) * 64 + (c2 - 48))); // decode the multibyte character
                    i = nextIndex + 1; // move the index forward
                } else {
                    // invalid UTF-8 byte, skip it
                    return i; // return the original index to indicate an invalid byte
                }
            } else {
                // missing continuation byte, skip it
                return i; // return the original index to indicate an invalid byte
            }
        } else {
            // invalid UTF-8 byte, skip it
            return i; // return the original index to indicate an invalid byte
        }
    }
    return i; // return the final index for the decoded string
