public class TimeRangeBuilder {

    public static List<TimeRange> buildTimeRanges(long start, long end) {
        // Check if start time and end time violate the fetched data duration
        long duration = end - start;
        if (duration > 3600) { // 3600 seconds = 1 hour
            // Split the time range into smaller parts no larger than 1 hour
            List<TimeRange> result = new ArrayList<>();
            int hours = 1;
            long currentStart = start;
            long currentEnd = start + 3600; // 1 hour

            while (currentEnd <= end) {
                TimeRange range = new TimeRange(currentStart, Math.min(currentEnd, end));
                result.add(range);
                currentStart = currentEnd;
                currentEnd = currentStart + 3600; // Next 1 hour
                hours++;
            }

            return result;
        } else {
            // Return the original time range if it is within the fetched data duration
            return List.of(new TimeRange(start, end));
        }
    }

    public static void main(String[] args) {
        List<TimeRange> timeRanges = buildTimeRanges(1633072800, 1633076400);
        for (TimeRange range : timeRanges) {
            System.out.println(range);
        }
    }
}

