public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }

    boolean isPrime = true;
    int candidate = Math.max(desiredCapacity, 2);

    while (candidate < desiredCapacity + 11 && candidate > 2) {
        for (int i = 2; i <= Math.sqrt(candidate); i++) {
            if (candidate % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate++;
    }

    throw new IllegalArgumentException("No prime number found for the given capacity.");
}

