public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (index < 0 || index + len > str.length()) {
        throw new IllegalArgumentException();
    }

    int length = 0;
    int i = index;

    while (i < index + len) {
        int b = str.charAt(i);
        if ((b & 0x80) == 0) {
            length++;
        } else if ((b & 0xE0) == 0xC0) {
            length += 2;
        } else if ((b & 0xF0) == 0xE0) {
            length += 3;
        } else if ((b & 0xF8) == 0xF0) {
            length += 4;
        }
        i++;
    }

    return length;
}

