public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        writeUpperBound(lb, 0);
        return lb;
    }
    int utfBytes = str.codePointCount(0, str.length());
    lb.reserve(utfBytes / 4 + Math.ceil(utfBytes % 4.0));
    for (int codePoint : str.codePoints().toArray()) {
        int charCount = Character.charCount(codePoint);
        if (charCount == 1) {
            writeChar(charCount, codePoint, session, lb);
            continue;
        }
        writeUpBound(lb, charCount);
        encodeUtf8Character(codePoint);
    }
    return lb;
}

